/// Registered customer accounts with email and password credentials, account
/// security status, and lifecycle control for login access.
///
/// This table is the canonical identity record for the customer actor. It
/// owns authentication credentials and account-level status only; profile
/// data, sessions, password resets, and email verification records are
/// handled in separate tables. Order history, reviews, and other marketplace
/// records reference this model indirectly and are preserved independently
/// when the customer account is deleted.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Email address used for customer login and account identity.
  email String

  /// Hashed password used for authentication.
  password_hash String

  /// Customer account state used to control login and administrative
  /// restrictions, such as active, banned, or deleted.
  account_status String

  /// Timestamp when the account was banned, if applicable.
  banned_at DateTime? @db.Timestamptz

  /// Timestamp when the customer account was soft-deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions shopping_mall_customer_sessions[]
  passwordResets shopping_mall_customer_password_resets[]
  emailVerifications shopping_mall_customer_email_verifications[]
  wishlists shopping_mall_wishlists[]
  cart shopping_mall_carts?
  orders shopping_mall_orders[]
  refundRequests shopping_mall_refund_requests[]
  reviews shopping_mall_reviews[]
  administratorRequestApplicantCustomers shopping_mall_administrator_request_applicant_customers[]
  profile shopping_mall_customer_profiles?

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([account_status, created_at])
  @@index([created_at])
}

/// Stores login sessions for customer accounts so authenticated access can
/// be tracked, expired, and revoked securely.
///
/// Each row represents one customer session created during login and
/// supports auditability for authentication events. The session belongs to
/// exactly one customer and records connection context plus expiration
/// metadata for secure session management.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// IP address used when the customer session was created.
  ip String

  /// Current request URL or page context associated with the session creation
  /// event.
  href String

  /// Referrer URL recorded at session creation time.
  referrer String

  /// Time when the session was created.
  created_at DateTime @db.Timestamptz

  /// Time when the session becomes invalid and can no longer be used.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, created_at], map: "shopping_mall_customer_sessions_shopping_mall_customer_adefa402")
}

