/// Registered seller accounts with email/password credentials, approval
/// workflow state, and account security status.
///
/// This table is the canonical identity record for seller actors in the
/// marketplace. It stores only the intrinsic account data needed for
/// authentication and lifecycle control, while seller profile data,
/// sessions, password resets, email verification, and approval review
/// history are managed in separate child tables.
///
/// The seller account can be used for login, approval gating, and
/// administrative moderation. Historical and dependent business artifacts
/// are preserved elsewhere so the account record remains normalized and
/// stable over time.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller login email address used for authentication and account lookup.
  email String

  /// Hashed seller password used for authentication.
  password_hash String

  /// Current administrative approval state for the seller account, such as
  /// pending, approved, or rejected.
  approval_status String

  /// Reason provided when the seller account is rejected by an administrator.
  rejection_reason String?

  /// Security and access status of the seller account, such as active,
  /// suspended, or banned.
  account_status String

  /// Timestamp when the seller account was approved, if approval has occurred.
  approved_at DateTime? @db.Timestamptz

  /// Timestamp when the seller account was rejected, if rejection has occurred.
  rejected_at DateTime? @db.Timestamptz

  /// Timestamp when the seller account was suspended, if the account is
  /// currently or previously suspended.
  suspended_at DateTime? @db.Timestamptz

  /// Timestamp when the seller account was banned, if the account is currently
  /// or previously banned.
  banned_at DateTime? @db.Timestamptz

  /// Timestamp of the most recent successful seller login.
  last_login_at DateTime? @db.Timestamptz

  /// Timestamp when the seller account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was soft-deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions shopping_mall_seller_sessions[]
  passwordResets shopping_mall_seller_password_resets[]
  emailVerifications shopping_mall_seller_email_verifications[]
  shipments shopping_mall_shipments[]
  sellerApprovalRequests shopping_mall_seller_approval_requests[]
  administratorRequestApplicantSeller shopping_mall_administrator_request_applicant_sellers?
  sellerProfile shopping_mall_seller_profiles?
  products shopping_mall_products[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([approval_status, account_status])
  @@index([created_at])
  @@index([approved_at])
  @@index([rejected_at])
}

