    "customer can only update items they own",
    async () => {
      await api.functional.shoppingMall.customer.items.update(
        customerAConnection,
        {
          cartItemId: anotherCartItemId,
          body: { quantity: 3 } satisfies IShoppingMallCartItem.IUpdate,
        },
      );
    },
  );
}

