      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          imageUri: `https://example.com/${RandomGenerator.alphabets(8)}-3.jpg`,
          displayOrder: 2,
          altText: "tertiary",
        } satisfies IShoppingMallProductImage.ICreate,
      },
    );
