export async function test_api_cancellation_request_snapshot_parent_scope_mismatch(
  connection: api.IConnection,
): Promise<void> {
  const administratorConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(administratorConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IShoppingMallAdministrator.IJoin,
  });
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: "https://example.com/register",
      referrer: "https://example.com",
      ip: "127.0.0.1",
    } satisfies IShoppingMallCustomer.IJoin,
  });
  const firstOrderItemId = typia.random<string & tags.Format<"uuid">>();
  const secondOrderItemId = typia.random<string & tags.Format<"uuid">>();
  const firstCancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_request_create(
      customerConnection,
      {
        params: { orderItemId: firstOrderItemId },
        body: {
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IShoppingMallCancellationRequest.ICreate,
      },
    );
  typia.assert(firstCancellationRequest);
  const secondCancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_request_create(
      customerConnection,
      {
        params: { orderItemId: secondOrderItemId },
        body: {
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IShoppingMallCancellationRequest.ICreate,
      },
    );
  typia.assert(secondCancellationRequest);
  TestValidator.notEquals(
    "cancellation request parents must differ",
    firstCancellationRequest.orderItem.id,
    secondCancellationRequest.orderItem.id,
  );
  await TestValidator.error(
    "snapshot must not be accessible through the wrong order item scope",
    async () => {
      await api.functional.shoppingMall.administrator.order_items.cancellation_request.snapshots.at(
        administratorConnection,
        {
          orderItemId: firstOrderItemId,
          snapshotId: secondCancellationRequest.id,
        },
      );
    },
  );
}

