export async function test_api_refund_request_snapshot_history_retrieval(
  connection: api.IConnection,
): Promise<void> {
  const output =
    await api.functional.shoppingMall.seller.order_items.refund_request.snapshots.index(
      connection,
      {
        orderItemId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          page: 1,
          limit: 10,
          sort: "createdAt",
          order: "desc",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
