  TestValidator.predicate(
    "pagination limit is positive",
    output.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    output.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    output.pagination.pages >= 0,
  );
  TestValidator.predicate("snapshots are ordered by createdAt descending", () =>
    output.data.every(
      (snapshot, index, array) =>
        index === 0 || array[index - 1].createdAt >= snapshot.createdAt,
    ),
  );
  for (const snapshot of output.data) {
    typia.assert(snapshot.refundRequest);
