              rejectedAt: null,
              suspendedAt: null,
              bannedAt: null,
              lastLoginAt: null,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              deletedAt: null,
              sellerProfile: null as never,
            },
            shopName: snapshot.shop_name,
            shopDescription: snapshot.shop_description,
            logoImageUrl: snapshot.logo_image_uri ?? "",
