}): Promise<IShoppingMallOrder> {
  const administrator =
    await MyGlobal.prisma.shopping_mall_administrators.findFirstOrThrow({
      where: {
        id: props.administrator.id,
        deleted_at: null,
      },
      select: {
        id: true,
        account_status: true,
        deleted_at: true,
      },
